esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// pg_up is a gauge: 1 = the exporter reached PostgreSQL, 0 = it could not.
// MIN() across series so a single unhealthy scrape target is not masked by a healthy one.
// Swap LAST_OVER_TIME for MIN_OVER_TIME to also catch transient dips inside the window.
| STATS `Postgres Up` = MIN(LAST_OVER_TIME(pg_up))
    BY resource.attributes.supabase_project_ref
// If pg_up is absent entirely the STATS produces no row, so a project that does not
// expose the metric never triggers a false alert.
| WHERE `Postgres Up` == 0
